def _country_code_for_region(region: Optional[str]) -> int:
    """Country calling code for an ISO region, falling back to +1 when unknown."""
    candidate = (region or "").strip().upper() or _FALLBACK_REGION
    try:
        code = phonenumbers.country_code_for_region(candidate)
    except Exception:  # pragma: no cover - defensive
        code = 0
    if not code:
        code = phonenumbers.country_code_for_region(_FALLBACK_REGION)
    return code


